// lib/collection/src/operations/types.rs (filter condition parsing)
// Filter conditions are optional structs, null is treated as None/absent
pub enum Filter {
    Must(Condition),
    MustNot(Condition),
    Should(Vec<Condition>),  // null should → empty Vec → no condition
}

// Common pattern in API: null fields are treated as absent/defaults
// No explicit validation rejects null filter values
